template <typename T>
class Expression {
public:
  Expression(const T& val) : value_(val) {}
  // Overloaded operators to build expression trees
  Expression<T> operator+(const Expression<T>& other) const {
    return Expression<T>(value_ + other.value_);
  }
  // ... other operators
  T evaluate() const { return value_; }
private:
  T value_;
};

int main() {
  Expression<double> a(1.0), b(2.0), c(3.0);
  Expression<double> result = a + b * c; // Expression tree built at compile time
  double finalResult = result.evaluate(); // Evaluation at runtime
  return 0;
}
